MENU_ITEMS = json.loads(MENU_ITEMS_RAW)

def seed_database():
    init_db()
    conn = get_db()
    cursor = conn.cursor()

    # 1. Admin & Owner
    cursor.execute("SELECT id FROM users WHERE email = ?", (DEFAULT_ADMIN["email"],))
    if not cursor.fetchone():
        cursor.execute("""
        INSERT INTO users (id, name, email, phone, password, role, created_at)
        VALUES (?, ?, ?, ?, ?, 'admin', datetime('now'))
        """, (DEFAULT_ADMIN["id"], DEFAULT_ADMIN["name"], DEFAULT_ADMIN["email"], DEFAULT_ADMIN["phone"], DEFAULT_ADMIN["password"]))

    cursor.execute("SELECT id FROM users WHERE email = ?", (DEFAULT_OWNER["email"],))
    if not cursor.fetchone():
        cursor.execute("""
        INSERT INTO users (id, name, email, phone, password, role, created_at)
        VALUES (?, ?, ?, ?, ?, 'owner', datetime('now'))
        """, (DEFAULT_OWNER["id"], DEFAULT_OWNER["name"], DEFAULT_OWNER["email"], DEFAULT_OWNER["phone"], DEFAULT_OWNER["password"]))

    # 2. Delivery Fleet
    for s in DELIVERY_STAFF:
        cursor.execute("SELECT id FROM delivery_staff WHERE id = ?", (s["id"],))
        if not cursor.fetchone():
            cursor.execute("""
            INSERT INTO delivery_staff (id, name, phone, vehicle, status, active_orders)
            VALUES (?, ?, ?, ?, ?, ?)
            """, (s["id"], s["name"], s["phone"], s["vehicle"], s["status"], s["active_orders"]))

    # 3. Seed/Refresh Menu Items
    cursor.execute("DELETE FROM menu_items")
    for item in MENU_ITEMS:
        cursor.execute("""
        INSERT INTO menu_items (
            id, name, category, subcategory, description, image_url,
            variants, base_price, tags, is_popular, is_seasonal, is_available, allergens
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?)
        """, (
            item["id"],
            item["name"],
            item["category"],
            item.get("subcategory"),
            item.get("description"),
            item.get("image_url"),
            json.dumps(item["variants"]),
            item["base_price"],
            json.dumps(item.get("tags", [])),
            1 if item.get("is_popular") else 0,
            1 if item.get("is_seasonal") else 0,
            item.get("allergens")
        ))

    conn.commit()
    conn.close()
    print(f"Successfully seeded 82 menu items to database.")

if __name__ == "__main__":
    seed_database()
